class Solution {
public:
    bool checkInclusion(string s1, string s2) {
        int n1 = s1.size(), n2 = s2.size();
        if (n1 > n2) return false;
        int c1[26] = {0}, c2[26] = {0};
        for (int i = 0; i < n1; i++) {
            c1[s1[i] - 'a']++;
            c2[s2[i] - 'a']++;
        }
        int matches = 0;
        for (int i = 0; i < 26; i++) if (c1[i] == c2[i]) matches++;
        if (matches == 26) return true;
        for (int i = n1; i < n2; i++) {
            int add = s2[i] - 'a';
            c2[add]++;
            if (c2[add] == c1[add]) matches++;
            else if (c2[add] == c1[add] + 1) matches--;
            int rem = s2[i - n1] - 'a';
            c2[rem]--;
            if (c2[rem] == c1[rem]) matches++;
            else if (c2[rem] == c1[rem] - 1) matches--;
            if (matches == 26) return true;
        }
        return false;
    }
};

