class Solution {
public:
    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {
        root = new Node();
        for (const string& word : words) {
            Node* node = root;
            for (char ch : word) {
                int i = ch - 'a';
                if (node->children[i] == nullptr) node->children[i] = new Node();
                node = node->children[i];
            }
            node->word = word;
        }
        vector<string> result;
        for (int r = 0; r < (int)board.size(); r++) {
            for (int c = 0; c < (int)board[0].size(); c++) {
                dfs(board, r, c, root, result);
            }
        }
        return result;
    }

private:
    struct Node {
        Node* children[26];
        string word;
        Node() {
            for (int i = 0; i < 26; i++) children[i] = nullptr;
        }
    };

    Node* root;

    void dfs(vector<vector<char>>& board, int r, int c, Node* parent, vector<string>& result) {
        if (r < 0 || c < 0 || r >= (int)board.size() || c >= (int)board[0].size()) return;
        char ch = board[r][c];
        if (ch == '#') return;
        Node* node = parent->children[ch - 'a'];
        if (node == nullptr) return;
        if (!node->word.empty()) {
            result.push_back(node->word);
            node->word.clear();
        }
        board[r][c] = '#';
        dfs(board, r + 1, c, node, result);
        dfs(board, r - 1, c, node, result);
        dfs(board, r, c + 1, node, result);
        dfs(board, r, c - 1, node, result);
        board[r][c] = ch;
    }
};

