class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        int freq[26] = {0};
        for (char t : tasks) freq[t - 'A']++;
        int maxFreq = *max_element(freq, freq + 26);
        int maxCount = 0;
        for (int f : freq) {
            if (f == maxFreq) maxCount++;
        }
        int frame = (maxFreq - 1) * (n + 1) + maxCount;
        return max(frame, (int)tasks.size());
    }
};

