class Twitter {
public:
    Twitter() : timeCounter(0) {}

    void postTweet(int userId, int tweetId) {
        tweets[userId].push_back({timeCounter++, tweetId});
    }

    vector<int> getNewsFeed(int userId) {
        vector<int> feed;
        priority_queue<tuple<int, int, int>> heap;
        auto pushLatest = [&](int user) {
            auto found = tweets.find(user);
            if (found == tweets.end() || found->second.empty()) return;
            int last = (int)found->second.size() - 1;
            heap.push({found->second[last].first, user, last});
        };
        pushLatest(userId);
        for (int followee : following[userId]) pushLatest(followee);
        while (!heap.empty() && (int)feed.size() < 10) {
            auto [time, user, index] = heap.top();
            heap.pop();
            feed.push_back(tweets[user][index].second);
            if (index > 0) heap.push({tweets[user][index - 1].first, user, index - 1});
        }
        return feed;
    }

    void follow(int followerId, int followeeId) {
        if (followerId != followeeId) following[followerId].insert(followeeId);
    }

    void unfollow(int followerId, int followeeId) {
        following[followerId].erase(followeeId);
    }

private:
    int timeCounter;
    unordered_map<int, vector<pair<int, int>>> tweets;
    unordered_map<int, unordered_set<int>> following;
};

