        int components = n;
        for (auto& edge : edges) {
            int a = find(edge[0]);
            int b = find(edge[1]);
            if (a != b) {
                parent[a] = b;
                components--;
            }
        }
        return components;
    }

private:
    vector<int> parent;

    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
