        vector<bool> visited(n, false);
        minDist[0] = 0;
        int total = 0;
        for (int step = 0; step < n; step++) {
            int u = -1;
            for (int i = 0; i < n; i++) {
                if (!visited[i] && (u == -1 || minDist[i] < minDist[u])) u = i;
            }
            visited[u] = true;
            total += minDist[u];
            for (int v = 0; v < n; v++) {
                if (visited[v]) continue;
                int dist = abs(points[u][0] - points[v][0]) + abs(points[u][1] - points[v][1]);
