class Solution {
public:
    string alienOrder(vector<string>& words) {
        unordered_map<char, unordered_set<char>> graph;
        unordered_map<char, int> indegree;
        for (const string& word : words) {
            for (char ch : word) {
                indegree[ch] += 0;
                graph[ch];
            }
        }
        for (size_t i = 0; i + 1 < words.size(); i++) {
            const string& a = words[i];
            const string& b = words[i + 1];
            size_t len = min(a.size(), b.size());
            if (a.size() > b.size() && a.compare(0, len, b) == 0) return "";
            for (size_t j = 0; j < len; j++) {
                if (a[j] != b[j]) {
                    if (!graph[a[j]].count(b[j])) {
                        graph[a[j]].insert(b[j]);
                        indegree[b[j]]++;
                    }
                    break;
                }
            }
        }
        queue<char> q;
        for (auto& entry : indegree) {
            if (entry.second == 0) q.push(entry.first);
        }
        string order;
        while (!q.empty()) {
            char ch = q.front();
            q.pop();
            order += ch;
            for (char next : graph[ch]) {
                if (--indegree[next] == 0) q.push(next);
            }
        }
        return order.size() == indegree.size() ? order : "";
    }
};

