    int longestIncreasingPath(vector<vector<int>>& matrix) {
        int m = matrix.size(), n = matrix[0].size();
        vector<vector<int>> memo(m, vector<int>(n, 0));
        int best = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                best = max(best, dfs(matrix, memo, r, c));
            }
        }
        return best;
    }

private:
    int dfs(vector<vector<int>>& matrix, vector<vector<int>>& memo, int r, int c) {
        if (memo[r][c] != 0) return memo[r][c];
        int dr[4] = {1, -1, 0, 0};
        int dc[4] = {0, 0, 1, -1};
        int best = 1;
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nc < 0 || nr >= (int)matrix.size() || nc >= (int)matrix[0].size()) continue;
            if (matrix[nr][nc] > matrix[r][c]) {
                best = max(best, 1 + dfs(matrix, memo, nr, nc));
            }
        }
        memo[r][c] = best;
        return best;
    }
};

