class Solution {
public:
    vector<int> minInterval(vector<vector<int>>& intervals, vector<int>& queries) {
        sort(intervals.begin(), intervals.end());
        int m = queries.size();
        vector<int> order(m);
        for (int i = 0; i < m; i++) order[i] = i;
        sort(order.begin(), order.end(), [&](int a, int b) { return queries[a] < queries[b]; });
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> heap;
        vector<int> answer(m, -1);
        size_t next = 0;
        for (int idx : order) {
            int q = queries[idx];
            while (next < intervals.size() && intervals[next][0] <= q) {
                heap.push({intervals[next][1] - intervals[next][0] + 1, intervals[next][1]});
                next++;
            }
            while (!heap.empty() && heap.top().second < q) heap.pop();
            if (!heap.empty()) answer[idx] = heap.top().first;
        }
        return answer;
    }
};

