class DetectSquares {
public:
    DetectSquares() {}

    void add(vector<int> point) {
        int key = point[0] * 1001 + point[1];
        if (counts[key] == 0) points.push_back({point[0], point[1]});
        counts[key]++;
    }

    int count(vector<int> point) {
        int x = point[0], y = point[1];
        int total = 0;
        for (auto& p : points) {
            int px = p.first, py = p.second;
            if (abs(px - x) != abs(py - y) || px == x) continue;
            int diagonal = counts[px * 1001 + py];
            int corner1 = counts[x * 1001 + py];
            int corner2 = counts[px * 1001 + y];
            total += diagonal * corner1 * corner2;
        }
        return total;
    }

private:
    unordered_map<int, int> counts;
    vector<pair<int, int>> points;
};

